import cocotb
from cocotb.triggers import Timer
from random import Random


class Reference:
    def __init__(self):
        self.reset()

    def reset(self):
        self.last_sel = 0
        self.last_addr = 0
        self.last_write = 0
        self.last_trans = 0
        self.last_size = 0
        self.last_phase = 0
        self.data_cfg = 0
        self.data_i = None
        self.rd_wr = 0
        self.state = 0
        self.ready = 1

        self.cfg = [0x03, 0x02, 0x35, 0xF5, 0, 0, 0, 0]
        self.estate = 0
        self.sck = 0
        self.ce = 1
        self.counter = 0
        self.data = [0, 0, 0, 0]
        self.known = [0, 0, 0, 0]

    def counts(self):
        mode = self.cfg[5]
        qspi = mode & 1
        qpi = (mode >> 1) & 1
        quad = qspi | qpi
        size = [1, 2, 4, 4, 4, 4, 4, 4][self.last_size]
        wait_start = (2 if qpi else 8) + (6 if quad else 24)
        data_start = wait_start + (self.cfg[4] if self.rd_wr else 0)
        short = self.cfg[6] | self.cfg[7]
        final = 8 if short else data_start + (2 if quad else 8) * size
        return qspi, qpi, quad, data_start, final

    def sized_data(self):
        if self.data_i is None:
            return None
        if self.last_size == 2:
            return self.data_i
        if self.last_size == 1:
            return (self.data_i >> (16 if self.last_addr & 2 else 0)) & 0xFFFF
        if self.last_size == 0:
            return (self.data_i >> (8 * (self.last_addr & 3))) & 0xFF
        return (self.data_i >> 24) & 0xFF

    def command(self):
        if self.cfg[6]:
            return self.cfg[2]
        if self.cfg[7]:
            return self.cfg[3]
        return self.cfg[0] if self.rd_wr else self.cfg[1]

    def pins(self):
        qspi, qpi, quad, data_start, final = self.counts()
        count = self.counter
        addr = self.last_addr & 0x7FFFFF
        cmd = self.command()
        data = self.sized_data()
        value = 0
        mask = 15

        if qpi:
            if count < 2:
                value = (cmd >> (4 * (1 - count))) & 15
            elif count < 8:
                value = (addr >> (4 * (7 - count))) & 15
            elif count < 16:
                if data is None:
                    mask = 0
                else:
                    n = count - 8
                    shift = 8 * (n // 2) + (4 if n % 2 == 0 else 0)
                    value = (data >> shift) & 15
        elif qspi:
            if count < 8:
                value = (cmd >> (7 - count)) & 1
            elif count < 14:
                value = (addr >> (4 * (13 - count))) & 15
            elif count < 22:
                if data is None:
                    mask = 0
                else:
                    n = count - 14
                    shift = 8 * (n // 2) + (4 if n % 2 == 0 else 0)
                    value = (data >> shift) & 15
        else:
            if count < 8:
                value = (cmd >> (7 - count)) & 1
            elif count < 32:
                value = (addr >> (31 - count)) & 1
            else:
                if data is None:
                    mask = 14
                else:
                    if count < 64:
                        n = count - 32
                        shift = 8 * (n // 8) + 7 - (n % 8)
                    else:
                        shift = 0
                    value = (data >> shift) & 1

        if qpi:
            if count < 8:
                enable = 15
            elif count < data_start and self.cfg[4] != 0 and self.rd_wr:
                enable = 0
            elif self.rd_wr:
                enable = 0
            else:
                enable = 15
        elif qspi:
            if count < 8:
                enable = 1
            elif count < 14:
                enable = 15
            elif count < data_start and self.cfg[4] != 0 and self.rd_wr:
                enable = 0
            elif self.rd_wr:
                enable = 0
            else:
                enable = 15
        else:
            enable = 1
        return value, mask, enable

    def read_data(self):
        value = 0
        mask = 0
        for i in range(4):
            value |= self.data[i] << (8 * i)
            mask |= self.known[i] << (8 * i)

        if self.last_size == 2:
            return value, mask
        if self.last_size == 1:
            shift = 16 if self.last_addr & 2 else 0
            return (value & 0xFFFF) << shift, (
                ((mask & 0xFFFF) << shift) | (0xFFFF << (16 - shift))
            )
        shift = 8 * (self.last_addr & 3) if self.last_size == 0 else 24
        return (value & 0xFF) << shift, (
            ((mask & 0xFF) << shift) | (0xFFFFFFFF ^ (0xFF << shift))
        )

    def advance(self, inp):
        qspi, qpi, quad, data_start, final = self.counts()
        done = self.counter == final
        phase = bool(inp["HTRANS"] & 2) and inp["HSEL"] and inp["HREADY"]
        start = bool(self.last_phase and not self.state and self.data_cfg)

        if data_start <= self.counter <= final and self.sck:
            index = (self.counter - data_start) >> (1 if quad else 3)
            if index < 4:
                if quad:
                    self.data[index] = ((self.data[index] << 4) | inp["din"]) & 0xFF
                    self.known[index] = ((self.known[index] << 4) | 15) & 0xFF
                else:
                    self.data[index] = (
                        (self.data[index] << 1) | ((inp["din"] >> 1) & 1)
                    ) & 0xFF
                    self.known[index] = ((self.known[index] << 1) | 1) & 0xFF

        if (
            (self.last_addr & 0x800000)
            and self.last_write
            and self.last_sel
            and (self.last_trans & 2)
        ):
            for i in range(8):
                if self.last_addr & (1 << (8 + i)):
                    width_mask = [255, 255, 255, 255, 15, 3, 1, 1][i]
                    self.cfg[i] = inp["HWDATA"] & width_mask

        if self.last_phase:
            self.data_i = inp["HWDATA"]
        if self.last_trans & 2:
            self.rd_wr = 0 if self.last_write else 1

        if not self.state:
            next_state = 1 if start else 0
            next_ready = 0 if self.last_phase or phase else 1
        else:
            finished = done and not (self.last_addr & 0x800000)
            next_state = 0 if finished else 1
            next_ready = 1 if finished else 0

        if not self.estate:
            next_estate = 1 if start else 0
        else:
            next_estate = 0 if done else 1

        if done:
            next_sck = 0
        elif not self.ce:
            next_sck = 1 - self.sck
        else:
            next_sck = self.sck

        if done:
            next_ce = 1
        elif self.estate:
            next_ce = 0
        else:
            next_ce = 1

        if self.sck and not done:
            next_counter = (self.counter + 1) & 255
        elif not self.estate:
            next_counter = 0
        else:
            next_counter = self.counter

        if inp["HREADY"]:
            self.last_sel = inp["HSEL"]
            self.last_addr = inp["HADDR"]
            self.last_write = inp["HWRITE"]
            self.last_trans = inp["HTRANS"]
        if (inp["HTRANS"] & 2) and self.ready:
            self.last_size = inp["HSIZE"]

        self.last_phase = 1 if phase else 0
        if phase:
            self.data_cfg = 0 if inp["HADDR"] & 0x800000 else 1

        self.state = next_state
        self.ready = next_ready
        self.estate = next_estate
        self.sck = next_sck
        self.ce = next_ce
        self.counter = next_counter


class Bench:
    def __init__(self, dut):
        self.dut = dut
        self.ref = Reference()
        self.rng = Random(0x534D4921)
        self.cycle = 0
        self.inp = {
            "HSEL": 0,
            "HADDR": 0,
            "HTRANS": 0,
            "HWRITE": 0,
            "HSIZE": 0,
            "HWDATA": 0,
            "HREADY": 1,
            "din": 0,
        }

    def drive(self):
        d = self.dut
        d.HSEL.value = self.inp["HSEL"]
        d.HADDR.value = self.inp["HADDR"]
        d.HTRANS.value = self.inp["HTRANS"]
        d.HWRITE.value = self.inp["HWRITE"]
        d.HSIZE.value = self.inp["HSIZE"]
        d.HWDATA.value = self.inp["HWDATA"]
        d.HREADY.value = self.inp["HREADY"]
        d.din.value = self.inp["din"]

    def bits_equal(self, signal, expected, mask, width, name):
        bits = str(signal.value)
        for bit in range(width):
            if (mask >> bit) & 1:
                actual = bits[width - 1 - bit]
                wanted = "1" if (expected >> bit) & 1 else "0"
                assert actual == wanted, (
                    name + " mismatch at cycle " + str(self.cycle)
                    + ", bit " + str(bit)
                    + ", actual " + bits
                    + ", expected " + str(expected)
                    + ", mask " + str(mask)
                    + ", serial count " + str(self.ref.counter)
                )

    def check(self):
        d = self.dut
        r = self.ref
        self.bits_equal(d.HREADYOUT, r.ready, 1, 1, "HREADYOUT")
        self.bits_equal(d.sck, r.sck, 1, 1, "sck")
        self.bits_equal(d.ce_n, r.ce, 1, 1, "ce_n")
        value, mask, enable = r.pins()
        self.bits_equal(d.dout, value, mask, 4, "dout")
        self.bits_equal(d.douten, enable, 15, 4, "douten")
        value, mask = r.read_data()
        self.bits_equal(d.HRDATA, value, mask, 32, "HRDATA")

    async def reset(self):
        self.dut.HCLK.value = 0
        self.dut.HRESETn.value = 0
        self.inp.update({
            "HSEL": 0, "HADDR": 0, "HTRANS": 0, "HWRITE": 0,
            "HSIZE": 0, "HWDATA": 0, "HREADY": 1, "din": 0,
        })
        self.drive()
        self.ref.reset()
        await Timer(2, unit="ns")
        self.check()
        self.dut.HCLK.value = 1
        await Timer(2, unit="ns")
        self.check()
        self.dut.HCLK.value = 0
        self.dut.HRESETn.value = 1
        await Timer(2, unit="ns")
        self.check()

    async def tick(self, **changes):
        self.inp.update(changes)
        self.dut.HCLK.value = 0
        self.drive()
        await Timer(2, unit="ns")
        self.check()
        self.ref.advance(self.inp)
        self.dut.HCLK.value = 1
        await Timer(2, unit="ns")
        self.cycle += 1
        self.check()

    async def transfer(self, addr, write, size, data, trans=2):
        assert self.ref.ready
        await self.tick(
            HSEL=1, HADDR=addr, HTRANS=trans, HWRITE=write,
            HSIZE=size, HWDATA=data, HREADY=1, din=self.rng.randrange(16),
        )
        for unused in range(400):
            ready = self.ref.ready
            await self.tick(
                HSEL=0, HADDR=0, HTRANS=0, HWRITE=0,
                HWDATA=data, HREADY=ready, din=self.rng.randrange(16),
            )
            if self.ref.ready:
                break
        else:
            assert False, "transaction did not complete"
        await self.tick(
            HSEL=0, HADDR=0, HTRANS=0, HWRITE=0,
            HREADY=1, HWDATA=data, din=self.rng.randrange(16),
        )

    async def config(self, select, value, high=0):
        await self.transfer(
            (high << 24) | 0x800000 | select, 1, 2, value
        )


@cocotb.test()
async def exercise_controller(dut):
    b = Bench(dut)
    await b.reset()

    # Inactive address phases and the independent HSIZE capture rule.
    for trans in (0, 1, 2, 3):
        await b.tick(
            HSEL=0, HADDR=0x801F00, HTRANS=trans, HWRITE=1,
            HSIZE=trans + 1, HREADY=0, HWDATA=0xFFFFFFFF,
        )
    await b.tick(HSEL=0, HTRANS=0, HREADY=1)

    # Default commands, both directions, all byte lanes, and all sizes.
    for size in range(8):
        for lane in range(4):
            addr = 0x123450 | lane | ((size * 13) << 8)
            await b.transfer(addr, (size + lane) & 1, size,
                             b.rng.getrandbits(32), 2 + (lane & 1))

    # Program independent command registers, then exercise all serial modes.
    await b.config(1 << 8, 0xA6, 0x91)
    await b.config(1 << 9, 0x59)
    await b.config(1 << 10, 0xC3)
    await b.config(1 << 11, 0x96)

    for mode in range(4):
        await b.config(1 << 13, mode)
        for wait in (0, 1, 5, 15):
            await b.config(1 << 12, wait)
            for size in range(4):
                for write in (0, 1):
                    lane = (mode + wait + size + write) & 3
                    addr = (
                        (b.rng.randrange(256) << 24)
                        | (b.rng.randrange(1 << 21) << 2)
                        | lane
                    )
                    await b.transfer(addr, write, size,
                                     b.rng.getrandbits(32),
                                     2 + b.rng.randrange(2))

    # Both special-command flags, including priority when both are set.
    for mode in range(4):
        await b.config(1 << 13, mode)
        for flags in (1, 2, 3):
            await b.config(1 << 14, flags & 1)
            await b.config(1 << 15, (flags >> 1) & 1)
            await b.transfer(0x456123, 0, 2, 0x12345678)
            await b.transfer(0x321056, 1, 0, 0xA59C3EF0)
        await b.config((1 << 14) | (1 << 15), 0)

    # Multiple register selects share the same write data.
    await b.config((1 << 8) | (1 << 9) | (1 << 12), 0xD7)
    await b.config((1 << 10) | (1 << 11), 0x6B)
    await b.transfer(0x704321, 0, 2, 0x96A53CC3)
    await b.transfer(0x107654, 1, 1, 0x19E7B42D)
    await b.transfer(0x808F00, 0, 0, 0xFFFFFFFF)

    # Assert asynchronous reset while a serial transfer is in progress.
    await b.tick(
        HSEL=1, HADDR=0x005A37, HTRANS=2, HWRITE=1,
        HSIZE=2, HWDATA=0x89ABCDEF, HREADY=1,
    )
    for unused in range(12):
        await b.tick(
            HSEL=0, HTRANS=0, HREADY=b.ref.ready,
            HWDATA=0x89ABCDEF, din=b.rng.randrange(16),
        )
    await b.reset()
    await b.transfer(0x00765432, 0, 2, 0x5AA59669)
    await b.transfer(0x00001203, 1, 0, 0xD2C3B4A5)

import cocotb
from cocotb.triggers import Timer
from random import Random


class Reference:
    def __init__(self):
        self.data_i = None
        self.data = [0, 0, 0, 0]
        self.known = [0, 0, 0, 0]
        self.reset()

    def reset(self):
        self.last_sel = 0
        self.last_addr = 0
        self.last_write = 0
        self.last_trans = 0
        self.last_size = 0
        self.last_phase = 0
        self.data_cfg = 0
        self.rd_wr = 0
        self.state = 0
        self.ready = 1

        self.rd_cmd = 0x03
        self.wr_cmd = 0x02
        self.eqpi_cmd = 0x35
        self.xqpi_cmd = 0xF5
        self.wait_states = 0
        self.mode = 0
        self.enter = 0
        self.exit = 0

        self.estate = 0
        self.sck = 0
        self.ce = 1
        self.counter = 0

    def counts(self):
        qspi = self.mode & 1
        qpi = (self.mode >> 1) & 1
        quad = qspi or qpi
        wait_start = (2 if qpi else 8) + (6 if quad else 24)
        data_start = wait_start + (self.wait_states if self.rd_wr else 0)
        size = 1 if self.last_size == 0 else 2 if self.last_size == 1 else 4
        final = 8 if self.enter or self.exit else data_start + (2 if quad else 8) * size
        return quad, data_start, final

    def command(self):
        if self.enter:
            return self.eqpi_cmd
        if self.exit:
            return self.xqpi_cmd
        return self.rd_cmd if self.rd_wr else self.wr_cmd

    def sized_write(self):
        if self.data_i is None:
            return None
        if self.last_size == 2:
            return self.data_i
        if self.last_size == 1:
            return (self.data_i >> (16 if self.last_addr & 2 else 0)) & 0xFFFF
        if self.last_size == 0:
            return (self.data_i >> (8 * (self.last_addr & 3))) & 0xFF
        return (self.data_i >> 24) & 0xFF

    def pins(self):
        count = self.counter
        qspi = self.mode & 1
        qpi = (self.mode >> 1) & 1
        quad, data_start, unused = self.counts()
        cmd = self.command()
        addr = self.last_addr & 0x7FFFFF
        write_data = self.sized_write()

        if qpi:
            if count < 2:
                dout = (cmd >> (4 * (1 - count))) & 15
            elif count < 8:
                dout = (addr >> (4 * (7 - count))) & 15
            elif count < 16:
                index = count - 8
                shift = 8 * (index // 2) + (4 if index % 2 == 0 else 0)
                dout = None if write_data is None else (write_data >> shift) & 15
            else:
                dout = 0
        elif qspi:
            if count < 8:
                dout = (cmd >> (7 - count)) & 1
            elif count < 14:
                dout = (addr >> (4 * (13 - count))) & 15
            elif count < 22:
                index = count - 14
                shift = 8 * (index // 2) + (4 if index % 2 == 0 else 0)
                dout = None if write_data is None else (write_data >> shift) & 15
            else:
                dout = 0
        else:
            if count < 8:
                dout = (cmd >> (7 - count)) & 1
            elif count < 32:
                dout = (addr >> (31 - count)) & 1
            else:
                if count < 64:
                    index = count - 32
                    shift = 8 * (index // 8) + 7 - (index % 8)
                else:
                    shift = 0
                dout = None if write_data is None else (write_data >> shift) & 1

        has_wait = self.wait_states != 0 and self.rd_wr
        if not quad:
            enable = 1
        elif qpi:
            if count < 8:
                enable = 15
            elif count < data_start and has_wait:
                enable = 0
            elif self.rd_wr:
                enable = 0
            else:
                enable = 15
        else:
            if count < 8:
                enable = 1
            elif count < 14:
                enable = 15
            elif count < data_start and has_wait:
                enable = 0
            elif self.rd_wr:
                enable = 0
            else:
                enable = 15
        return dout, enable

    def read_value(self):
        value = 0
        mask = 0
        for i in range(4):
            value |= self.data[i] << (8 * i)
            mask |= self.known[i] << (8 * i)

        if self.last_size == 2:
            return value, mask
        if self.last_size == 1:
            shift = 16 if self.last_addr & 2 else 0
            return (value & 0xFFFF) << shift, (
                ((mask & 0xFFFF) << shift) | (0xFFFF0000 if shift == 0 else 0xFFFF)
            )
        if self.last_size == 0:
            shift = 8 * (self.last_addr & 3)
        else:
            shift = 24
        lane = 0xFF << shift
        return (value & 0xFF) << shift, ((mask & 0xFF) << shift) | (0xFFFFFFFF ^ lane)

    def step(self, inp):
        phase = int(bool(inp["HTRANS"] & 2) and inp["HSEL"] and inp["HREADY"])
        start = self.last_phase and not self.state and self.data_cfg
        quad, data_start, final = self.counts()
        done = self.counter == final

        if data_start <= self.counter <= final and self.sck:
            index = (self.counter - data_start) >> (1 if quad else 3)
            if index < 4:
                if quad:
                    self.data[index] = ((self.data[index] << 4) | inp["din"]) & 0xFF
                    self.known[index] = ((self.known[index] << 4) | 15) & 0xFF
                else:
                    self.data[index] = ((self.data[index] << 1) | ((inp["din"] >> 1) & 1)) & 0xFF
                    self.known[index] = ((self.known[index] << 1) | 1) & 0xFF

        if (
            (self.last_addr & 0x800000)
            and self.last_write
            and self.last_sel
            and (self.last_trans & 2)
        ):
            word = inp["HWDATA"]
            if self.last_addr & (1 << 8):
                self.rd_cmd = word & 0xFF
            if self.last_addr & (1 << 9):
                self.wr_cmd = word & 0xFF
            if self.last_addr & (1 << 10):
                self.eqpi_cmd = word & 0xFF
            if self.last_addr & (1 << 11):
                self.xqpi_cmd = word & 0xFF
            if self.last_addr & (1 << 12):
                self.wait_states = word & 15
            if self.last_addr & (1 << 13):
                self.mode = word & 3
            if self.last_addr & (1 << 14):
                self.enter = word & 1
            if self.last_addr & (1 << 15):
                self.exit = word & 1

        if self.last_phase:
            self.data_i = inp["HWDATA"]

        next_rd_wr = self.rd_wr
        if self.last_trans & 2:
            next_rd_wr = 1 - self.last_write

        next_state = self.state
        if not self.state:
            if start:
                next_state = 1
            next_ready = 0 if self.last_phase or phase else 1
        else:
            if done and not (self.last_addr & 0x800000):
                next_state = 0
                next_ready = 1
            else:
                next_ready = 0

        next_estate = self.estate
        if not self.estate:
            if start:
                next_estate = 1
        elif done:
            next_estate = 0

        if done:
            next_sck = 0
        elif not self.ce:
            next_sck = 1 - self.sck
        else:
            next_sck = self.sck

        if done:
            next_ce = 1
        elif self.estate:
            next_ce = 0
        else:
            next_ce = 1

        if self.sck and not done:
            next_counter = (self.counter + 1) & 0xFF
        elif not self.estate:
            next_counter = 0
        else:
            next_counter = self.counter

        if (inp["HTRANS"] & 2) and self.ready:
            self.last_size = inp["HSIZE"]

        if inp["HREADY"]:
            self.last_sel = inp["HSEL"]
            self.last_addr = inp["HADDR"]
            self.last_write = inp["HWRITE"]
            self.last_trans = inp["HTRANS"]

        if phase:
            self.data_cfg = 0 if inp["HADDR"] & 0x800000 else 1
        self.last_phase = phase
        self.rd_wr = next_rd_wr
        self.state = next_state
        self.ready = next_ready
        self.estate = next_estate
        self.sck = next_sck
        self.ce = next_ce
        self.counter = next_counter

    def check(self, dut, cycle):
        assert int(dut.HREADYOUT.value) == self.ready, f"cycle {cycle}: HREADYOUT"
        assert int(dut.sck.value) == self.sck, f"cycle {cycle}: sck"
        assert int(dut.ce_n.value) == self.ce, f"cycle {cycle}: ce_n"
        dout, enable = self.pins()
        assert int(dut.douten.value) == enable, (
            f"cycle {cycle}: douten, count={self.counter}, mode={self.mode}"
        )
        if dout is not None:
            assert int(dut.dout.value) == dout, (
                f"cycle {cycle}: dout, count={self.counter}, mode={self.mode}, "
                f"expected={dout}, got={dut.dout.value}"
            )

        value, mask = self.read_value()
        bits = str(dut.HRDATA.value)
        assert len(bits) == 32
        for bit in range(32):
            if (mask >> bit) & 1:
                expected = "1" if (value >> bit) & 1 else "0"
                assert bits[31 - bit] == expected, (
                    f"cycle {cycle}: HRDATA bit {bit}, expected {expected}, got {bits}"
                )


class Bench:
    def __init__(self, dut):
        self.dut = dut
        self.ref = Reference()
        self.rng = Random(73129)
        self.cycle = 0
        self.inp = {
            "HSEL": 0,
            "HADDR": 0,
            "HTRANS": 0,
            "HWRITE": 0,
            "HSIZE": 0,
