    def __init__(self):
        self.data_i = None
        self.data = [0, 0, 0, 0]
        self.known = [0, 0, 0, 0]
        self.reset()

    def reset(self):
        self.last_sel = 0
        self.last_addr = 0
        self.last_write = 0
        self.last_trans = 0
        self.last_size = 0
        self.last_phase = 0
        self.data_cfg = 0
        self.rd_wr = 0
        self.state = 0
        self.ready = 1

        self.rd_cmd = 3
        self.wr_cmd = 2
        self.eqpi_cmd = 0x35
        self.xqpi_cmd = 0xF5
        self.wait_states = 0
        self.mode = 0
        self.enter = 0
        self.exit = 0

        self.estate = 0
        self.sck = 0
        self.ce = 1
        self.counter = 0

    def derived(self):
        qspi = self.mode & 1
        qpi = (self.mode >> 1) & 1
        quad = qspi | qpi
        wait_start = (2 if qpi else 8) + (6 if quad else 24)
        data_start = wait_start + (self.wait_states if self.rd_wr else 0)
        size = 1 if self.last_size == 0 else 2 if self.last_size == 1 else 4
        short = self.enter | self.exit
        final_count = 8 if short else data_start + (2 if quad else 8) * size
        done = int(self.counter == final_count)
        start = int(self.last_phase and not self.state and self.data_cfg)
        if self.enter:
            cmd = self.eqpi_cmd
        elif self.exit:
            cmd = self.xqpi_cmd
        elif self.rd_wr:
            cmd = self.rd_cmd
        else:
            cmd = self.wr_cmd
        return qspi, qpi, quad, data_start, final_count, done, start, cmd

    def sized_data(self):
        if self.data_i is None:
            return None
        if self.last_size == 2:
            return self.data_i
        if self.last_size == 1:
            shift = 16 if self.last_addr & 2 else 0
            return (self.data_i >> shift) & 0xFFFF
        if self.last_size == 0:
            return (self.data_i >> (8 * (self.last_addr & 3))) & 0xFF
        return (self.data_i >> 24) & 0xFF

    def pins(self):
        qspi, qpi, quad, data_start, final_count, done, start, cmd = self.derived()
        count = self.counter
        addr = self.last_addr & 0x7FFFFF
        data = self.sized_data()

        if qpi:
            if count < 2:
                out = (cmd >> (4 * (1 - count))) & 15
            elif count < 8:
                out = (addr >> (4 * (7 - count))) & 15
            elif count < 16:
                if data is None:
                    out = None
                else:
                    j = count - 8
                    shift = 8 * (j // 2) + (4 if j % 2 == 0 else 0)
                    out = (data >> shift) & 15
            else:
                out = 0
        elif qspi:
            if count < 8:
                out = (cmd >> (7 - count)) & 1
            elif count < 14:
                out = (addr >> (4 * (13 - count))) & 15
            elif count < 22:
                if data is None:
                    out = None
                else:
                    j = count - 14
                    shift = 8 * (j // 2) + (4 if j % 2 == 0 else 0)
                    out = (data >> shift) & 15
            else:
