            if count < 8:
                out = (cmd >> (7 - count)) & 1
            elif count < 32:
                out = (addr >> (31 - count)) & 1
            elif data is None:
                out = None
            else:
                if count < 64:
                    j = count - 32
                    shift = 8 * (j // 8) + 7 - (j % 8)
                else:
                    shift = 0
                out = (data >> shift) & 1

        has_wait = bool(self.wait_states and self.rd_wr)
        if qpi:
