            if self.last_addr & (1 << 14):
                self.enter = value & 1
            if self.last_addr & (1 << 15):
                self.exit = value & 1

        if self.last_phase:
            self.data_i = inp["wdata"]

        if self.last_trans & 2:
            next_rd_wr = int(not self.last_write)
        else:
            next_rd_wr = self.rd_wr

        if not self.state:
            next_state = int(bool(start))
            next_ready = int(not (self.last_phase or addr_phase))
        else:
            finish = bool(done and not (self.last_addr & 0x800000))
            next_state = 0 if finish else 1
            next_ready = int(finish)

