        if self.enter:
            cmd = self.eqpi_cmd
        elif self.exit:
            cmd = self.xqpi_cmd
        elif self.rd_wr:
            cmd = self.rd_cmd
        else:
            cmd = self.wr_cmd
        return qspi, qpi, quad, data_start, final_count, done, start, cmd

    def sized_data(self):
        if self.data_i is None:
            return None
        if self.last_size == 2:
            return self.data_i
        if self.last_size == 1:
            shift = 16 if self.last_addr & 2 else 0
            return (self.data_i >> shift) & 0xFFFF
        if self.last_size == 0:
            return (self.data_i >> (8 * (self.last_addr & 3))) & 0xFF
        return (self.data_i >> 24) & 0xFF

    def pins(self):
        qspi, qpi, quad, data_start, final_count, done, start, cmd = self.derived()
        count = self.counter
        addr = self.last_addr & 0x7FFFFF
        data = self.sized_data()

        if qpi:
            if count < 2:
                out = (cmd >> (4 * (1 - count))) & 15
            elif count < 8:
                out = (addr >> (4 * (7 - count))) & 15
            elif count < 16:
                if data is None:
                    out = None
                else:
                    j = count - 8
                    shift = 8 * (j // 2) + (4 if j % 2 == 0 else 0)
                    out = (data >> shift) & 15
            else:
                out = 0
        elif qspi:
            if count < 8:
                out = (cmd >> (7 - count)) & 1
            elif count < 14:
                out = (addr >> (4 * (13 - count))) & 15
            elif count < 22:
                if data is None:
                    out = None
                else:
                    j = count - 14
                    shift = 8 * (j // 2) + (4 if j % 2 == 0 else 0)
                    out = (data >> shift) & 15
            else:
                out = 0
        else:
            if count < 8:
                out = (cmd >> (7 - count)) & 1
            elif count < 32:
                out = (addr >> (31 - count)) & 1
            elif data is None:
                out = None
            else:
                if count < 64:
                    j = count - 32
                    shift = 8 * (j // 8) + 7 - (j % 8)
                else:
                    shift = 0
                out = (data >> shift) & 1

        has_wait = bool(self.wait_states and self.rd_wr)
        if qpi:
            if count < 8:
                enable = 15
            elif count < data_start and has_wait:
                enable = 0
            elif self.rd_wr:
                enable = 0
            else:
                enable = 15
        elif qspi:
            if count < 8:
                enable = 1
            elif count < 14:
                enable = 15
            elif count < data_start and has_wait:
                enable = 0
            elif self.rd_wr:
                enable = 0
            else:
                enable = 15
        else:
            enable = 1
        return out, enable

    def read_value(self):
        value = 0
        mask = 0
        for i in range(4):
            value |= self.data[i] << (8 * i)
            mask |= self.known[i] << (8 * i)

        if self.last_size == 2:
            return value, mask
        if self.last_size == 1:
            shift = 16 if self.last_addr & 2 else 0
            return (value & 0xFFFF) << shift, (
                ((mask & 0xFFFF) << shift) | (0xFFFF << (16 - shift))
            )
        if self.last_size == 0:
            shift = 8 * (self.last_addr & 3)
        else:
            shift = 24
        lane_mask = 0xFF << shift
        return (value & 0xFF) << shift, (
            ((mask & 0xFF) << shift) | (0xFFFFFFFF ^ lane_mask)
        )

    def check(self, dut, cycle):
        assert int(dut.HREADYOUT.value) == self.ready, f"ready at cycle {cycle}"
        assert int(dut.sck.value) == self.sck, f"sck at cycle {cycle}"
        assert int(dut.ce_n.value) == self.ce, f"ce_n at cycle {cycle}"
        out, enable = self.pins()
        assert int(dut.douten.value) == enable, f"douten at cycle {cycle}"
        if out is not None:
            assert int(dut.dout.value) == out, (
                f"dout at cycle {cycle}, count {self.counter}, "
                f"mode {self.mode}, expected {out}"
            )

        expected, mask = self.read_value()
        bits = str(dut.HRDATA.value)
        for bit in range(32):
            if (mask >> bit) & 1:
                want = "1" if (expected >> bit) & 1 else "0"
                assert bits[31 - bit] == want, (
                    f"HRDATA bit {bit} at cycle {cycle}, "
                    f"size {self.last_size}, address {self.last_addr:x}"
                )

    def edge(self, inp):
        qspi, qpi, quad, data_start, final_count, done, start, cmd = self.derived()
        addr_phase = int(bool(inp["trans"] & 2) and inp["sel"] and inp["ready"])

        if data_start <= self.counter <= final_count and self.sck:
            index = (self.counter - data_start) >> (1 if quad else 3)
            if index < 4:
                if quad:
                    self.data[index] = ((self.data[index] << 4) | inp["din"]) & 0xFF
                    self.known[index] = ((self.known[index] << 4) | 15) & 0xFF
                else:
                    self.data[index] = (
                        (self.data[index] << 1) | ((inp["din"] >> 1) & 1)
                    ) & 0xFF
                    self.known[index] = ((self.known[index] << 1) | 1) & 0xFF

        if (
            (self.last_addr & 0x800000)
            and self.last_write
            and self.last_sel
            and (self.last_trans & 2)
        ):
            value = inp["wdata"]
            if self.last_addr & (1 << 8):
                self.rd_cmd = value & 0xFF
            if self.last_addr & (1 << 9):
                self.wr_cmd = value & 0xFF
            if self.last_addr & (1 << 10):
                self.eqpi_cmd = value & 0xFF
            if self.last_addr & (1 << 11):
                self.xqpi_cmd = value & 0xFF
            if self.last_addr & (1 << 12):
                self.wait_states = value & 15
            if self.last_addr & (1 << 13):
                self.mode = value & 3
            if self.last_addr & (1 << 14):
                self.enter = value & 1
            if self.last_addr & (1 << 15):
                self.exit = value & 1

        if self.last_phase:
            self.data_i = inp["wdata"]

        if self.last_trans & 2:
            next_rd_wr = int(not self.last_write)
        else:
            next_rd_wr = self.rd_wr

        if not self.state:
            next_state = int(bool(start))
            next_ready = int(not (self.last_phase or addr_phase))
        else:
            finish = bool(done and not (self.last_addr & 0x800000))
            next_state = 0 if finish else 1
            next_ready = int(finish)

        if not self.estate:
            next_estate = int(bool(start))
        else:
            next_estate = 0 if done else 1

        if done:
            next_sck = 0
            next_ce = 1
        else:
            next_sck = self.sck ^ 1 if not self.ce else self.sck
            next_ce = 0 if self.estate else 1

        if self.sck and not done:
            next_counter = (self.counter + 1) & 0xFF
        elif not self.estate:
            next_counter = 0
        else:
            next_counter = self.counter

        if (inp["trans"] & 2) and self.ready:
            self.last_size = inp["size"] & 7

        if inp["ready"]:
            self.last_sel = inp["sel"]
            self.last_addr = inp["addr"] & 0xFFFFFFFF
            self.last_write = inp["write"]
            self.last_trans = inp["trans"]

        if addr_phase:
            self.data_cfg = int(not (inp["addr"] & 0x800000))
        self.last_phase = addr_phase
        self.rd_wr = next_rd_wr
        self.state = next_state
        self.ready = next_ready
        self.estate = next_estate
        self.sck = next_sck
        self.ce = next_ce
        self.counter = next_counter


class Bench:
    def __init__(self, dut):
        self.dut = dut
        self.ref = Reference()
        self.rng = Random(819263)
        self.cycle = 0

    async def tick(
        self, sel=0, addr=0, trans=0, write=0, size=0,
        wdata=0, ready=1, din=None
    ):
        if din is None:
            din = self.rng.randrange(16)
        inp = {
            "sel": sel, "addr": addr, "trans": trans, "write": write,
            "size": size, "wdata": wdata, "ready": ready, "din": din,
        }
        d = self.dut
        d.HSEL.value = sel
        d.HADDR.value = addr
        d.HTRANS.value = trans
        d.HWRITE.value = write
        d.HSIZE.value = size
        d.HWDATA.value = wdata
        d.HREADY.value = ready
        d.din.value = din
        await Timer(1, unit="ns")
        self.ref.check(d, self.cycle)
        d.HCLK.value = 1
        self.ref.edge(inp)
        await Timer(1, unit="ns")
        d.HCLK.value = 0
        await Timer(1, unit="ns")
        self.cycle += 1

    async def reset(self):
        d = self.dut
        d.HCLK.value = 0
        d.HRESETn.value = 0
        d.HSEL.value = 0
        d.HADDR.value = 0
        d.HTRANS.value = 0
        d.HWRITE.value = 0
        d.HSIZE.value = 0
        d.HWDATA.value = 0
        d.HREADY.value = 1
        d.din.value = 0
        self.ref.reset()
        await Timer(2, unit="ns")
        self.ref.check(d, self.cycle)
        d.HRESETn.value = 1
        await Timer(1, unit="ns")
        await self.tick()

    async def access(self, addr, write, size, data=0, trans=2):
        assert self.ref.ready == 1
        await self.tick(
            sel=1, addr=addr, trans=trans, write=write,
            size=size, wdata=data, ready=1
        )
        for i in range(350):
            if self.ref.ready:
                break
            await self.tick(
                sel=0, addr=addr, trans=0, write=write,
                size=size, wdata=data, ready=0
            )
        else:
            assert False, "transaction did not complete"
        await self.tick(
            sel=0, addr=addr, trans=0, write=write,
            size=size, wdata=data, ready=1
        )

    async def config(self, select, value, upper=0):
        await self.access(upper | 0x800000 | select, 1, 2, value)


@cocotb.test()
async def controller_test(dut):
    b = Bench(dut)
    await b.reset()

    # Default commands, byte-lane steering, and both AHB transfer types.
    for size in range(4):
        for lane in range(4):
            for write in (0, 1):
                addr = 0x512340 | lane
                data = b.rng.getrandbits(32)
                await b.access(addr, write, size, data, 2 + ((lane + write) & 1))

    # Program each command separately, including ignored upper address bits.
    await b.config(1 << 8, 0xA6, 0xC1000000)
    await b.config(1 << 9, 0x59)
    await b.config(1 << 10, 0x9C)
    await b.config(1 << 11, 0xE3)

    # All mode encodings, wait extremes, lane selections, and nonstandard sizes.
    for mode in range(4):
        await b.config(1 << 13, mode)
        for wait in (0, 1, 5, 15):
            await b.config(1 << 12, wait)
            for size in (0, 1, 2, 3, 7):
                lane = (mode + wait + size) & 3
                for write in (0, 1):
                    addr = (b.rng.getrandbits(23) & ~3) | lane
                    addr |= b.rng.randrange(256) << 24
                    await b.access(
                        addr, write, size, b.rng.getrandbits(32),
                        2 + b.rng.randrange(2)
                    )

    # Simultaneous configuration selects and command priority.
    await b.config((1 << 8) | (1 << 9) | (1 << 10) | (1 << 11), 0xB7)
    for mode in range(4):
        await b.config(1 << 13, mode)
        for flags in (1, 2, 3):
            await b.config(1 << 14, flags & 1)
            await b.config(1 << 15, (flags >> 1) & 1)
            await b.access(0x654321, 0, 2, 0x13579BDF)
            await b.access(0x123456, 1, 0, 0xA5C36E91)
        await b.config((1 << 14) | (1 << 15), 0)

    # Configuration reads must not modify registers.
    await b.access(0xFF800000 | (0xFF << 8), 0, 2, 0xFFFFFFFF)
    await b.access(0x1234AB, 1, 2, 0xFEDCBA98)

    # Address acceptance and last-size capture have different gating.
    for i in range(24):
        await b.tick(
            sel=0, addr=b.rng.getrandbits(32), trans=2 + (i & 1),
            write=i & 1, size=i & 7, wdata=b.rng.getrandbits(32),
            ready=i & 1
        )
    for i in range(8):
        await b.tick(
            sel=1, addr=0x800000 | (1 << (8 + i)), trans=i & 1,
            write=1, size=i, wdata=0xFFFFFFFF, ready=1
        )
    await b.tick()

    # Change write data while a configuration data phase is stalled:
    # the final value is the one present on the last qualifying edge.
    await b.tick(
        sel=1, addr=0x800000 | (1 << 8) | (1 << 9),
        trans=2, write=1, size=2, wdata=0, ready=1
    )
    await b.tick(addr=0x800300, write=1, size=2, wdata=0x12, ready=0)
    await b.tick(addr=0x800300, write=1, size=2, wdata=0x34, ready=0)
    await b.tick(addr=0x800300, write=1, size=2, wdata=0x56, ready=1)
    await b.access(0x456789, 0, 2, 0)
    await b.access(0x456789, 1, 2, 0x12345678)

    # Asynchronous reset during an active serial operation.
    await b.config(1 << 13, 0)
    await b.config(1 << 12, 0)
    await b.tick(sel=1, addr=0x123456, trans=2, write=1, size=2, ready=1)
    for i in range(20):
        await b.tick(addr=0x123456, write=1, size=2, wdata=0x89ABCDEF, ready=0)
    await b.reset()
    await b.access(0x3ABCDE, 0, 2, 0)
    await b.access(0x123403, 1, 0, 0xA1B2C3D4)

    # Additional randomized transactions with independently programmed modes.
    for i in range(40):
        if i % 5 == 0:
            await b.config(1 << 13, b.rng.randrange(4))
            await b.config(1 << 12, b.rng.randrange(16))
        await b.access(
            b.rng.getrandbits(32) & ~0x800000,
            b.rng.randrange(2),
            b.rng.randrange(8),
            b.rng.getrandbits(32),
            2 + b.rng.randrange(2),
        )
